(function(){'use strict';let known=null,audio=null,lastLocation=0;const original=window.fetch.bind(window);window.fetch=async function(...args){const response=await original(...args);try{if(String(args[0]).includes('/api/delivery/state')&&response.ok){const data=await response.clone().json(),ids=(data.offers||[]).map(x=>x.id);if(known&&ids.some(id=>!known.has(id)))notify();known=new Set(ids)}}catch{}return response};async function unlock(askPermission=false){try{const C=window.AudioContext||window.webkitAudioContext;audio=audio||new C();if(audio.state==='suspended')await audio.resume()}catch{}if(askPermission&&'Notification'in window&&Notification.permission==='default')try{await Notification.requestPermission()}catch{}return !!audio}function tone(start,delay=0){if(!audio||audio.state!=='running')return;const at=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(start,at);o.frequency.exponentialRampToValueAtTime(520,at+.5);g.gain.setValueAtTime(.24,at);g.gain.exponentialRampToValueAtTime(.001,at+.65);o.connect(g).connect(audio.destination);o.start(at);o.stop(at+.7)}function notify(){try{unlock(false);tone(980,0);tone(1180,.8);tone(980,1.6)}catch{}if('vibrate'in navigator)navigator.vibrate([350,120,350,120,500]);if('Notification'in window&&Notification.permission==='granted'){navigator.serviceWorker?.ready.then(r=>r.active?.postMessage({type:'VUPPI_OFFER',body:'Uma nova entrega está disponível. Abra para aceitar.'})).catch(()=>{});if(!navigator.serviceWorker?.controller)new Notification('Nova entrega VUPPI',{body:'Uma nova entrega está disponível. Abra o aplicativo para aceitar.',icon:'/pwa-icon.svg',tag:'vuppi-new-delivery',renotify:true,requireInteraction:true})}}async function lookup(input,target){const cep=input.value.replace(/\D/g,'');if(cep.length!==8)return;const r=await original('/api/delivery/cep?cep='+cep,{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.message||'CEP n\u00e3o encontrado.');target.value=d.address+', ';target.focus()}async function autocomplete(input){if(!input||input.dataset.autocompleteReady)return;input.dataset.autocompleteReady='1';const box=document.createElement('div');box.className='address-suggestions';input.parentElement.style.position='relative';input.parentElement.appendChild(box);let timer,controller;input.addEventListener('input',()=>{clearTimeout(timer);controller?.abort();const q=input.value.trim();if(q.length<3){box.replaceChildren();return}timer=setTimeout(async()=>{controller=new AbortController();try{const r=await original('/api/delivery/address?q='+encodeURIComponent(q),{credentials:'same-origin',signal:controller.signal}),d=await r.json();box.innerHTML=(d.results||[]).map((x,i)=>'<button type="button" data-i="'+i+'">'+String(x.label).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]))+'</button>').join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{input.value=d.results[Number(b.dataset.i)].label;box.replaceChildren();input.dispatchEvent(new Event('change',{bubbles:true}))})}catch(e){if(e.name!=='AbortError')box.replaceChildren()}},350)});document.addEventListener('click',e=>{if(e.target!==input&&!box.contains(e.target))box.replaceChildren()})}function location(){if(!navigator.geolocation||Date.now()-lastLocation<15000)return;lastLocation=Date.now();navigator.geolocation.getCurrentPosition(async p=>{try{await original('/api/delivery/action',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'location',data:{lat:p.coords.latitude,lng:p.coords.longitude}})})}catch{}},()=>{},{enableHighAccuracy:true,maximumAge:15000,timeout:8000})}window.VUPPIAlerts={unlock,notify};addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('input[name="address"],input[name="destination"]').forEach(autocomplete);for(const [id,name] of [['registerCep','address'],['orderCep','destination']]){const input=document.getElementById(id),target=document.querySelector(`[name="${name}"]`);input?.addEventListener('input',()=>{if(input.value.replace(/\D/g,'').length===8)lookup(input,target).catch(e=>{const m=document.getElementById('message');if(m)m.textContent=e.message})})}document.getElementById('availability')?.addEventListener('click',()=>{unlock(true);location()});document.addEventListener('pointerdown',()=>unlock(false),{once:true,passive:true});setInterval(()=>{if(!document.getElementById('courierHome')?.hidden)location()},15000)})})();
